SELECT id, category, price, cost, stock_qty, MAX(cost) OVER w_grp AS running_max_cost, MIN(cost) OVER w_grp AS running_min_cost, AVG(cost) OVER w_grp AS running_avg_cost, CORR(stock_qty, price) OVER w_ordered AS corr_stock_qty_price FROM products WINDOW w_grp AS (PARTITION BY brand ORDER BY price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_ordered AS (PARTITION BY category);
